"""Compilation of recurring nonuniform allgather reservations.

The compiler turns a weighted allgather proposal into a *plan*:

``trees``    weighted logical out-trees over the participant set (one record
             per demanded root, weight = that root's chunk demand),
``routes``   per ordered participant pair the exact number of unicast chunk
             copies that the logical trees require, each bound to a recipe,
``recipes``  a shared acyclic serial-route circuit; every leaf is a single
             directed physical link traversal.

Ordinary (non participant) vertices are pure forwarders: they may never
multicast or aggregate.  A recipe therefore only ever concatenates walks at
non participant vertices, and every leaf occurrence is charged with the full
multiplicity of the route that references it.

All arithmetic is exact integer arithmetic.
"""

from collections import deque

MAX_TREE_RECORDS = 8192
MAX_ROUTE_RECORDS = 32768
MAX_RECIPE_NODES = 65536


# ---------------------------------------------------------------------------
# small helpers
# ---------------------------------------------------------------------------

def _bfs_tree(adj, source, expandable, order_key=None):
    """Breadth first tree over ``adj`` that only expands ``expandable`` nodes.

    ``adj[x]`` holds ``(link_id, direction, neighbour)`` triples.  Nodes that
    are not expandable (participants other than the source) are attached to the
    tree but never expanded, so every root-to-node path only uses ordinary
    forwarding vertices in its interior.
    """
    parent = {source: None}
    order = [source]
    queue = deque([source])
    while queue:
        x = queue.popleft()
        nbrs = adj[x]
        if order_key is not None:
            nbrs = sorted(nbrs, key=order_key)
        for link, direction, y in nbrs:
            if y in parent:
                continue
            parent[y] = (x, link, direction)
            order.append(y)
            if y in expandable:
                queue.append(y)
    return parent, order


class _Flow:
    """Tiny exact integer maximum flow (Dinic) over an explicit arc list."""

    __slots__ = ("n", "to", "cap", "head", "nxt")

    def __init__(self, n):
        self.n = n
        self.to = []
        self.cap = []
        self.head = [-1] * n
        self.nxt = []

    def add(self, u, v, c):
        if c <= 0:
            return
        self.to.append(v)
        self.cap.append(c)
        self.nxt.append(self.head[u])
        self.head[u] = len(self.to) - 1
        self.to.append(u)
        self.cap.append(0)
        self.nxt.append(self.head[v])
        self.head[v] = len(self.to) - 1

    def _bfs(self, s, t):
        level = [-1] * self.n
        level[s] = 0
        queue = deque([s])
        while queue:
            x = queue.popleft()
            e = self.head[x]
            while e != -1:
                if self.cap[e] > 0 and level[self.to[e]] < 0:
                    level[self.to[e]] = level[x] + 1
                    queue.append(self.to[e])
                e = self.nxt[e]
        return level

    def _dfs(self, x, t, f, level, it):
        if x == t:
            return f
        while it[x] != -1:
            e = it[x]
            y = self.to[e]
            if self.cap[e] > 0 and level[y] == level[x] + 1:
                d = self._dfs(y, t, f if f < self.cap[e] else self.cap[e], level, it)
                if d > 0:
                    self.cap[e] -= d
                    self.cap[e ^ 1] += d
                    return d
            it[x] = self.nxt[e]
        return 0

    def maxflow(self, s, t):
        flow = 0
        while True:
            level = self._bfs(s, t)
            if level[t] < 0:
                return flow
            it = list(self.head)
            while True:
                f = self._dfs(s, t, 1 << 62, level, it)
                if f == 0:
                    break
                flow += f

    def source_side(self, s):
        """Vertices reachable from ``s`` in the residual graph (a min cut side)."""
        seen = [False] * self.n
        seen[s] = True
        stack = [s]
        while stack:
            x = stack.pop()
            e = self.head[x]
            while e != -1:
                if self.cap[e] > 0 and not seen[self.to[e]]:
                    seen[self.to[e]] = True
                    stack.append(self.to[e])
                e = self.nxt[e]
        return seen


# ---------------------------------------------------------------------------
# deficient cut witnesses
# ---------------------------------------------------------------------------

def find_deficient_cut(n, links, caps, participants, demands):
    """Search for a vertex set ``S`` witnessing that admission is impossible.

    The witness condition of the protocol is strict::

        sum(p*b_l for links with exactly one endpoint in S)
            < sum(r_v for participants v in S)

    With ``C`` the participant set and ``D`` the total demand this is
    equivalent to ``sum_{v in C, v not in S} r_v + cross(S) < D`` where
    ``cross(S)`` is the total capacity of the links leaving ``S``.  That is a
    minimum cut of the network that connects a super source to every
    participant with capacity ``r_v`` and gives every physical link its
    per-period capacity in both directions.  Fixing one participant on the
    sink side keeps the witness admissible (it must not contain every
    participant), so the search is exact.

    Returns ``(cut, deficit)`` where ``cut`` is ``None`` when no admissible
    witness exists and ``deficit`` is the best (possibly non positive) slack
    ``sum(r_v in S) - cross(S)``.
    """
    part = sorted(participants)
    total = sum(demands[v] for v in part)
    if not part:
        return None, 0

    src = n
    best_cut = None
    best_deficit = None
    for sink in part:
        flow = _Flow(n + 1)
        for v in part:
            flow.add(src, v, demands[v])
        for link, rate in caps.items():
            u, w = links[link]
            flow.add(u, w, rate)
            flow.add(w, u, rate)
        value = flow.maxflow(src, sink)
        seen = flow.source_side(src)
        cut = [v for v in range(n) if seen[v]]
        demand = sum(demands[v] for v in part if seen[v])
        cross = 0
        inside = set(cut)
        for link, rate in caps.items():
            u, w = links[link]
            if (u in inside) != (w in inside):
                cross += rate
        deficit = demand - cross
        if best_deficit is None or deficit > best_deficit:
            best_deficit = deficit
            best_cut = cut
        if deficit > 0:
            return cut, deficit
    return None, (best_deficit if best_deficit is not None else 0)


# ---------------------------------------------------------------------------
# plan construction
# ---------------------------------------------------------------------------

def _logical_trees(participants, demands, reach):
    """Breadth first spanning trees of the participant graph, one per root."""
    part = set(participants)
    roots = [v for v in participants if demands[v] > 0]
    trees = {}
    loads = {}
    for root in roots:
        parent = {root: None}
        order = [root]
        queue = deque([root])
        while queue:
            x = queue.popleft()
            for y in reach[x]:
                if y in parent:
                    continue
                parent[y] = x
                order.append(y)
                queue.append(y)
        if len(parent) != len(part):
            return None, None
        trees[root] = parent
        weight = demands[root]
        for node in order[1:]:
            key = (parent[node], node)
            loads[key] = loads.get(key, 0) + weight
    return trees, loads


def _paths_from(adj, source, expandable, targets, order_key=None):
    """Physical walks from ``source`` to each target using ordinary forwarders."""
    parent, order = _bfs_tree(adj, source, expandable, order_key)
    chains = {}
    for target in targets:
        if target not in parent or target == source:
            continue
        chain = []
        node = target
        while node != source:
            prev, link, direction = parent[node]
            chain.append((link, direction))
            node = prev
        chain.reverse()
        chains[target] = chain
    return chains


def _emit(recipes, recipe_of, chains, source, parent_order, parent_of):
    """Create recipe nodes for every chain, sharing the common prefixes."""
    ids = {}
    for node in parent_order:
        if node == source:
            continue
        prev, link, direction = parent_of[node]
        leaf = [0, link, direction]
        leaf_id = len(recipes)
        recipes.append(leaf)
        if prev == source:
            ids[node] = leaf_id
        else:
            concat = [1, ids[prev], leaf_id]
            concat_id = len(recipes)
            recipes.append(concat)
            ids[node] = concat_id
    return ids


def _plan_loads(plan, n, links, caps, participants, demands):
    """Recompute the aggregate physical load of a plan (used for validation)."""
    loads = {}
    for record in plan["routes"]:
        u, v, count, recipe = record
        for link, direction in _expand(plan["recipes"], recipe, links):
            key = (link, direction)
            loads[key] = loads.get(key, 0) + count
    return loads


def _expand(recipes, node_id, links, memo=None):
    """Expand a recipe into the list of (link, direction) traversals."""
    if memo is None:
        memo = {}
    stack = [node_id]
    out = []
    while stack:
        nid = stack.pop()
        if nid in memo:
            out.extend(memo[nid])
            continue
        node = recipes[nid]
        if node[0] == 0:
            memo[nid] = [(node[1], node[2])]
            out.append((node[1], node[2]))
        else:
            left = _expand(recipes, node[1], links, memo)
            right = _expand(recipes, node[2], links, memo)
            memo[nid] = left + right
            out.extend(left)
            out.extend(right)
    return out


def validate_plan(plan, n, links, caps, participants, demands, period):
    """Check a plan against every structural rule of the protocol."""
    part = set(participants)
    total = sum(demands.values())
    trees = plan["trees"]
    routes = plan["routes"]
    recipes = plan["recipes"]
    if len(trees) > MAX_TREE_RECORDS or len(routes) > MAX_ROUTE_RECORDS:
        return False
    if len(recipes) > MAX_RECIPE_NODES:
        return False

    # --- recipes -----------------------------------------------------------
    ends = {}

    def walk(nid, stack):
        if nid in stack:
            return None
        if nid in ends:
            return ends[nid]
        if not isinstance(nid, int) or isinstance(nid, bool):
            return None
        if nid < 0 or nid >= len(recipes):
            return None
        node = recipes[nid]
        if not isinstance(node, list) or len(node) not in (2, 3):
            return None
        if node[0] == 0:
            if len(node) != 3:
                return None
            link, direction = node[1], node[2]
            if not isinstance(link, int) or isinstance(link, bool):
                return None
            if not isinstance(direction, int) or isinstance(direction, bool):
                return None
            if link < 0 or link >= len(links) or direction not in (0, 1):
                return None
            u, v = links[link]
            ends[nid] = (u, v) if direction == 0 else (v, u)
            return ends[nid]
        if node[0] == 1:
            if len(node) != 3:
                return None
            left = walk(node[1], stack | {nid})
            if left is None:
                return None
            right = walk(node[2], stack | {nid})
            if right is None:
                return None
            if left[1] != right[0]:
                return None
            if left[1] in part:
                return None
            ends[nid] = (left[0], right[1])
            return ends[nid]
        return None

    for nid in range(len(recipes)):
        if walk(nid, frozenset()) is None:
            return False

    # --- trees -------------------------------------------------------------
    weight = {}
    logical = {}
    for record in trees:
        if not isinstance(record, list) or len(record) != 3:
            return False
        root, count, edges = record
        if not isinstance(root, int) or isinstance(root, bool):
            return False
        if root not in part:
            return False
        if not isinstance(count, int) or isinstance(count, bool):
            return False
        if count <= 0 or count > total:
            return False
        if not isinstance(edges, list) or len(edges) != len(part) - 1:
            return False
        indeg = {}
        adj = {}
        seen = set()
        for edge in edges:
            if not isinstance(edge, list) or len(edge) != 2:
                return False
            u, v = edge
            if not isinstance(u, int) or isinstance(u, bool):
                return False
            if not isinstance(v, int) or isinstance(v, bool):
                return False
            if u not in part or v not in part or u == v:
                return False
            if (u, v) in seen:
                return False
            seen.add((u, v))
            indeg[v] = indeg.get(v, 0) + 1
            adj.setdefault(u, []).append(v)
        if indeg.get(root, 0) != 0:
            return False
        for node in part:
            if node != root and indeg.get(node, 0) != 1:
                return False
        # reachability from the root
        stack = [root]
        visited = {root}
        while stack:
            x = stack.pop()
            for y in adj.get(x, ()):
                if y not in visited:
                    visited.add(y)
                    stack.append(y)
        if visited != part:
            return False
        weight[root] = weight.get(root, 0) + count
        for edge in edges:
            key = (edge[0], edge[1])
            logical[key] = logical.get(key, 0) + count

    for node in part:
        if demands[node] == 0:
            if weight.get(node, 0) != 0:
                return False
        elif weight.get(node, 0) != demands[node]:
            return False

    # --- routes ------------------------------------------------------------
    routed = {}
    for record in routes:
        if not isinstance(record, list) or len(record) != 4:
            return False
        u, v, count, recipe = record
        if not isinstance(u, int) or isinstance(u, bool):
            return False
        if not isinstance(v, int) or isinstance(v, bool):
            return False
        if u not in part or v not in part or u == v:
            return False
        if not isinstance(count, int) or isinstance(count, bool):
            return False
        if count <= 0 or count > total:
            return False
        if not isinstance(recipe, int) or isinstance(recipe, bool):
            return False
        if recipe < 0 or recipe >= len(recipes):
            return False
        walk_end = ends.get(recipe)
        if walk_end is None or walk_end[0] != u or walk_end[1] != v:
            return False
        key = (u, v)
        routed[key] = routed.get(key, 0) + count
    for key, value in logical.items():
        if routed.get(key, 0) != value:
            return False
    for key, value in routed.items():
        if logical.get(key, 0) != value:
            return False

    # --- physical load -----------------------------------------------------
    loads = _plan_loads(plan, n, links, caps, participants, demands)
    for (link, direction), value in loads.items():
        if value > caps.get(link, 0):
            return False
    return True


def _try_variant(n, links, envelope, period, participants, demands, variant):
    """Build one concrete plan; returns the plan or ``None``."""
    part = set(participants)
    ordinary = set(range(n)) - part
    adj = [[] for _ in range(n)]
    for link in sorted(envelope):
        u, v = links[link]
        adj[u].append((link, 0, v))
        adj[v].append((link, 1, u))

    # physical reachability between participants (interior vertices ordinary)
    reach = {}
    src_parent = {}
    src_order = {}
    for u in participants:
        parent, order = _bfs_tree(adj, u, ordinary)
        src_parent[u] = parent
        src_order[u] = order
        reach[u] = [w for w in parent if w in part and w != u]
    for u in participants:
        for w in reach[u]:
            if w not in reach.get(w, ()):  # pragma: no cover - sanity
                pass

    trees, logical = _logical_trees(participants, demands, reach)
    if trees is None:
        return None

    # choose physical walks, balancing the load where possible
    outgoing = {}
    for (u, v), count in logical.items():
        outgoing[u] = outgoing.get(u, 0) + count
    sources = sorted(outgoing, key=lambda x: (-outgoing[x], x))

    loads = {}
    chains = {}
    for u in sources:
        targets = [v for (uu, v) in logical if uu == u]
        order_key = None
        if variant == "balanced":
            def order_key(item, _u=u):
                link, direction, _y = item
                return (loads.get((link, direction), 0), link, direction)
        found = _paths_from(adj, u, ordinary, targets, order_key)
        for v in targets:
            chain = found.get(v)
            if chain is None:
                return None
            chains[(u, v)] = chain
            count = logical[(u, v)]
            for link, direction in chain:
                key = (link, direction)
                loads[key] = loads.get(key, 0) + count

    caps = {link: period * rate for link, rate in envelope.items()}
    for (link, direction), value in loads.items():
        if value > caps[link]:
            return None

    # --- emit the plan -----------------------------------------------------
    recipes = []
    route_records = []
    for u in sources:
        parent = src_parent[u]
        order = src_order[u]
        targets = [v for (uu, v) in logical if uu == u]
        ids = _emit(recipes, None, chains, u, order, parent)
        for v in sorted(targets):
            route_records.append([u, v, logical[(u, v)], ids[v]])
        if len(recipes) > MAX_RECIPE_NODES:
            return None
    tree_records = []
    for root in sorted(trees):
        parent = trees[root]
        edges = []
        for node, prev in parent.items():
            if node != root:
                edges.append([prev, node])
        tree_records.append([root, demands[root], edges])
    plan = {"trees": tree_records, "routes": route_records, "recipes": recipes}
    if not validate_plan(plan, n, links, caps, participants, demands, period):
        return None
    return plan


def compile_plan(n, links, envelope, period, participants, demands):
    """Compile a proposal.

    Returns ``(plan, cut)``.  ``plan`` is a valid plan when the proposal is
    admissible, otherwise ``None`` and ``cut`` holds the vertices of a
    deficient cut witness (best effort when the witness cannot be made
    strictly deficient).
    """
    cut, deficit = find_deficient_cut(n, links, {l: period * r for l, r in envelope.items()},
                                      participants, demands)
    if cut is not None:
        return None, cut
    for variant in ("plain", "balanced"):
        plan = _try_variant(n, links, envelope, period, participants, demands, variant)
        if plan is not None:
            return plan, None
    if cut is None:
        # no strictly deficient witness exists; return the closest one so that
        # the denial still points at the bottleneck.
        cut, _ = find_deficient_cut(n, links, {l: period * r for l, r in envelope.items()},
                                    participants, demands)
        if cut is None:
            cut = sorted(participants)[:1]
    return None, cut
